// Author: MiYu. Region membership, enter/leave/range transitions and player chat use live session producers.
#include "session.h"
#include <bit>
#include <cmath>

namespace war3 {
void ScriptSession::spatialEvents() {
    std::vector<std::uint32_t> ids;for(auto eventHandle:eventHandles_)if(alive(eventHandle,NativeKind::Event)){auto kind=std::get<ScriptEvent>(objects_[eventHandle-handleBase].state).kind;if(kind==ScriptEvent::Kind::RegionEnter || kind==ScriptEvent::Kind::RegionLeave || kind==ScriptEvent::Kind::UnitRange)ids.push_back(eventHandle);}
    for(auto id:ids){if(!alive(id,NativeKind::Event))continue;auto event=std::get<ScriptEvent>(objects_[id-handleBase].state);std::set<std::uint32_t> inside;std::shared_ptr<SpatialRegion> region;std::shared_ptr<UnitState> target;
        if(event.kind==ScriptEvent::Kind::UnitRange){if(!alive(event.target,NativeKind::Unit))continue;target=units_.at(event.target);}else{if(!alive(event.target,NativeKind::Region))continue;region=std::get<std::shared_ptr<SpatialRegion>>(objects_[event.target-handleBase].state);}
        for(auto& [unitId,u]:units_){bool contains=region?region->contains({u->x,u->y}):unitId!=event.target && std::hypot(std::bit_cast<float>(u->x.bits())-std::bit_cast<float>(target->x.bits()),std::bit_cast<float>(u->y.bits())-std::bit_cast<float>(target->y.bits()))<=std::bit_cast<float>(event.limit.bits());if(contains)inside.insert(unitId);}std::get<ScriptEvent>(objects_[id-handleBase].state).inside=inside;
        auto& candidates=event.kind==ScriptEvent::Kind::RegionLeave?event.inside:inside;for(auto unitId:candidates){bool changed=event.kind==ScriptEvent::Kind::RegionLeave?!inside.contains(unitId):!event.inside.contains(unitId);if(!changed || !alive(unitId,NativeKind::Unit))continue;ScriptContext context;context.triggerUnit=unitId;context.triggerPlayer=handleBase+units_.at(unitId)->owner;if(region)context.triggeringRegion=event.target;if(event.kind==ScriptEvent::Kind::RegionLeave)context.leavingUnit=unitId;else context.enteringUnit=unitId;fire(id,context);}
    }
}
void ScriptSession::chat(unsigned owner,const std::string& message,ChatChannel channel,std::optional<unsigned> recipient) {
    if(owner>=16 || message.size()>1024 || unsigned(channel)>2 || (recipient && (*recipient>=16 || channel!=ChatChannel::All)))throw std::runtime_error("Invalid player chat input");std::uint16_t audience=0xffff;if(recipient)audience=std::uint16_t((1u<<owner)|(1u<<*recipient));else if(channel!=ChatChannel::All){audience=std::uint16_t(1u<<owner);for(unsigned i=0;i<16;++i)if(channel==ChatChannel::Allies?(config_.players[owner].alliances[i]&1)!=0:config_.players[i].observer)audience|=std::uint16_t(1u<<i);}auto prefix=recipient?"[私聊] ":channel==ChatChannel::Allies?"[盟友] ":channel==ChatChannel::Observers?"[观察者] ":"";displayText(16,0,0,10,prefix+config_.players[owner].name+": "+message,audience,true);std::vector<std::uint32_t> events;for(auto eventHandle:eventHandles_)if(alive(eventHandle,NativeKind::Event)){auto& e=std::get<ScriptEvent>(objects_[eventHandle-handleBase].state);if(e.kind==ScriptEvent::Kind::Chat && e.target==owner && (e.exact?message==e.match:message.find(e.match)!=std::string::npos))events.push_back(eventHandle);}for(auto id:events){if(!alive(id,NativeKind::Event))continue;ScriptContext context;context.triggerPlayer=handleBase+owner;context.chat=message;context.chatMatch=std::get<ScriptEvent>(objects_[id-handleBase].state).match;fire(id,context);}
}
void ScriptSession::bindSpatialEvents() {
    auto region=[this](jass::Value value){return std::get<std::shared_ptr<SpatialRegion>>(object(value,NativeKind::Region).state);};auto point=[](jass::Value x,jass::Value y){return WorldPoint{jass::Real::fromBits(x.bits),jass::Real::fromBits(y.bits)};};
    bind("CreateRegion","region",{},[this](auto&,auto){return create(NativeKind::Region);});
    bind("RemoveRegion","nothing",{"region"},[this](auto& vm,auto a){destroy(a[0],NativeKind::Region);return vm.nothing();});
    for(auto [name,clear]:std::initializer_list<std::pair<const char*,bool>>{{"RegionAddRect",false},{"RegionClearRect",true}})bind(name,"nothing",{"region","rect"},[this,region,clear](auto& vm,auto a){auto rect=std::get<WorldRect>(object(a[1],NativeKind::Rect).state);if(clear)region(a[0])->clear(rect);else region(a[0])->add(rect);return vm.nothing();});
    for(auto [name,clear]:std::initializer_list<std::pair<const char*,bool>>{{"RegionAddCell",false},{"RegionClearCell",true}})bind(name,"nothing",{"region","real","real"},[region,point,clear](auto& vm,auto a){auto rect=SpatialRegion::cell(point(a[1],a[2]));if(clear)region(a[0])->clear(rect);else region(a[0])->add(rect);return vm.nothing();});
    for(auto [name,clear]:std::initializer_list<std::pair<const char*,bool>>{{"RegionAddCellAtLoc",false},{"RegionClearCellAtLoc",true}})bind(name,"nothing",{"region","location"},[this,region,clear](auto& vm,auto a){auto rect=SpatialRegion::cell(std::get<WorldPoint>(object(a[1],NativeKind::Location).state));if(clear)region(a[0])->clear(rect);else region(a[0])->add(rect);return vm.nothing();});
    bind("IsPointInRegion","boolean",{"region","real","real"},[region,point](auto& vm,auto a){return vm.boolean(region(a[0])->contains(point(a[1],a[2])));});
    bind("IsLocationInRegion","boolean",{"region","location"},[this,region](auto& vm,auto a){return vm.boolean(region(a[0])->contains(std::get<WorldPoint>(object(a[1],NativeKind::Location).state)));});
    bind("IsUnitInRegion","boolean",{"region","unit"},[this,region](auto& vm,auto a){auto& u=unit(a[1]);return vm.boolean(region(a[0])->contains({u.x,u.y}));});
    auto registration=[this](jass::Value trigger,ScriptEvent event){object(trigger,NativeKind::Trigger);event.owner=trigger.bits;auto handle=create(NativeKind::Event);std::get<ScriptEvent>(object(handle,NativeKind::Event).state)=std::move(event);return handle;};
    for(auto [name,leave]:std::initializer_list<std::pair<const char*,bool>>{{"TriggerRegisterEnterRegion",false},{"TriggerRegisterLeaveRegion",true}})bind(name,"event",{"trigger","region","boolexpr"},[this,region,registration,leave](auto&,auto a){ScriptEvent event;event.kind=leave?ScriptEvent::Kind::RegionLeave:ScriptEvent::Kind::RegionEnter;event.target=a[1].bits;event.event=leave?6:5;event.filter=expression(a[2]);auto area=region(a[1]);for(auto& [id,u]:units_)if(area->contains({u->x,u->y}))event.inside.insert(id);return registration(a[0],std::move(event));});
    bind("TriggerRegisterUnitInRange","event",{"trigger","unit","real","boolexpr"},[this,registration](auto&,auto a){auto& target=unit(a[1]);auto radius=std::bit_cast<float>(a[2].bits);if(!std::isfinite(radius) || radius<0)throw std::runtime_error("Invalid unit range event radius");ScriptEvent event;event.kind=ScriptEvent::Kind::UnitRange;event.target=a[1].bits;event.event=8;event.limit=jass::Real::fromBits(a[2].bits);event.filter=expression(a[3]);for(auto& [id,u]:units_)if(id!=a[1].bits && std::hypot(std::bit_cast<float>(u->x.bits())-std::bit_cast<float>(target.x.bits()),std::bit_cast<float>(u->y.bits())-std::bit_cast<float>(target.y.bits()))<=radius)event.inside.insert(id);return registration(a[0],std::move(event));});
    bind("TriggerRegisterPlayerChatEvent","event",{"trigger","player","string","boolean"},[this,registration](auto&,auto a){ScriptEvent event;event.kind=ScriptEvent::Kind::Chat;event.event=16;event.target=playerId(a[1]);event.match=a[2].text?*a[2].text:std::string{};event.exact=a[3].bits!=0;return registration(a[0],std::move(event));});
    bind("GetTriggeringRegion","region",{},[this](auto& vm,auto){return vm.handle("region",contexts_.empty()?0:contexts_.back().triggeringRegion);});
    for(auto [name,leave]:std::initializer_list<std::pair<const char*,bool>>{{"GetEnteringUnit",false},{"GetLeavingUnit",true}})bind(name,"unit",{},[this,leave](auto& vm,auto){return vm.handle("unit",contexts_.empty()?0:leave?contexts_.back().leavingUnit:contexts_.back().enteringUnit);});
    bind("GetEventPlayerChatString","string",{},[this](auto& vm,auto){return vm.string(contexts_.empty()?std::string{}:contexts_.back().chat);});
    bind("GetEventPlayerChatStringMatched","string",{},[this](auto& vm,auto){return vm.string(contexts_.empty()?std::string{}:contexts_.back().chatMatch);});
}
}
